}

contracts/interfaces/IAgentEnsRegistry/I.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.28;

import {IAccessControl} from "@openzeppelin/contracts/access/IAccessControl.sol";

import {IAgentEnsRegistryStates} from "./IAgentEnsRegistryStates.sol";
import {IAgentEnsRegistryEvents} from "./IAgentEnsRegistryEvents.sol";
import {IAgentEnsRegistryErrors} from "./IAgentEnsRegistryErrors.sol";
import {IAgentEnsRegistryAgentActions} from "./IAgentEnsRegistryAgentActions.sol";
import {IAgentEnsRegistryAdminActions} from "./IAgentEnsRegistryAdminActions.sol";

interface IAgentEnsRegistry is
    IAccessControl,
    IAgentEnsRegistryStates,
    IAgentEnsRegistryEvents,
    IAgentEnsRegistryErrors,
    IAgentEnsRegistryAgentActions,
    IAgentEnsRegistryAdminActions
{

}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.28;

interface IAgentEnsRegistryAdminActions {
    /// @dev Update the collections manager used to gate write access.
    function setManager(address newManager) external;

    /// @dev Update the parent ENS node under which agent subnodes live.
    function setParentNode(bytes32 newParentNode) external;
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.28;

import {KeyValue} from "../../types/KeyValue.sol";

interface IAgentEnsRegistryAgentActions {
    /// @dev Provision an agent's ENS subnode and seed its text records. Must run
    ///      before `setAgentText` and reverts if already provisioned. `records`
    ///      must include a non-empty `url`; the reserved `avatar` key is rejected
    ///      (derived on read from the collection's `default` image). Caller must
    ///      control the agent (NFT owner or registered wallet) and `collection`
    ///      must be manager-registered.
    /// @param collection The agent collection contract address.
    /// @param tokenId The agent token identifier.
    /// @param records The initial text records (key/value pairs).
    function initAgentTexts(
        address collection,
        uint256 tokenId,
        KeyValue[] calldata records
    ) external;

    /// @dev Update one text record on a provisioned subnode (reverts
    ///      `NotProvisioned` otherwise). Same caller/collection rules as
    ///      `initAgentTexts`; `key` may not be the reserved `avatar`.
    /// @param collection The agent collection contract address.
    /// @param tokenId The agent token identifier.
    /// @param key The text record key (e.g. "url").
    /// @param value The text record value.
    function setAgentText(
        address collection,
        uint256 tokenId,
        string calldata key,
        string calldata value
    ) external;
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.28;

interface IAgentEnsRegistryErrors {
    /// @dev Collection is not registered with the configured manager.
    error UnknownCollection(address collection);

    /// @dev Caller is neither the agent NFT owner nor a registered agent wallet.
    error NotAgentOwnerOrWallet(address collection, uint256 tokenId, address caller);

    /// @dev `initAgentTexts` was called for an agent that is already provisioned.
    error AlreadyProvisioned(address collection, uint256 tokenId);

    /// @dev `setAgentText` was called before the agent was initialized with `initAgentTexts`.
    error NotProvisioned(address collection, uint256 tokenId);

    /// @dev A mandatory key (`url`) would be left unset — either missing from
    ///      `initAgentTexts` or cleared to empty via `setAgentText`.
    error MissingRequiredKey(string key);

    /// @dev Key is resolved by the registry itself (e.g. `avatar`) and cannot
    ///      be stored.
    error ReservedKey(string key);
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.28;

interface IAgentEnsRegistryEvents {
    /// @dev Emitted when an agent text record is written.
    event AgentTextUpdated(
        address indexed collection,
        uint256 indexed tokenId,
        string key,
        string value
    );

    /// @dev Emitted when an agent subnode is first provisioned and bound to its NFT.
    event SubnodeProvisioned(
        address indexed collection,
        uint256 indexed tokenId,
        bytes32 indexed node,
        string label
    );

    /// @dev Emitted when the collections manager address is updated by admin.
    event ManagerUpdated(address indexed newManager);

    /// @dev Emitted when the parent node is updated by admin.
    event ParentNodeUpdated(bytes32 indexed newParentNode);
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.28;

interface IAgentEnsRegistryStates {
    /// @dev The collections manager used to gate write access.
    function manager() external view returns (address);

    /// @dev The parent ENS node under which agent subnodes live (namehash of parent domain).
    function parentNode() external view returns (bytes32);

    /// @dev Whether a given agent subnode has been provisioned through this registry.
    function provisioned(bytes32 node) external view returns (bool);

    /// @dev Reverse lookup from an agent subnode to its NFT; zero tuple for
    ///      unprovisioned nodes.
    function agentRef(bytes32 node) external view returns (address collection, uint256 tokenId);

    /// @dev ENS `text` shape, so a gateway can read this registry directly.
    ///      Empty string for unset keys. `avatar` is derived on read from the
    ///      collection's `default` image as an ENSIP-12 URI (bare CIDs gain an
    ///      `ipfs://` prefix) and cannot be set via `setAgentText`.
    function text(bytes32 node, string calldata key) external view returns (string memory);

    /// @dev ENS `addr` shape. Derived on read from the agent's first registered
    ///      wallet; `address(0)` for unprovisioned nodes or agents with no wallet.
    function addr(bytes32 node) external view returns (address);
}

contracts/libraries/UriUtils.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.28;

library UriUtils {
    /// @dev True when `value` contains a `://` scheme separator.
    function hasScheme(string memory value) internal pure returns (bool) {
        bytes memory raw = bytes(value);
        for (uint256 i = 0; i + 2 < raw.length; i++) {
            if (raw[i] == ":" && raw[i + 1] == "/" && raw[i + 2] == "/") return true;
        }
        return false;
    }

    /// @dev Prepend `prefix` unless `value` is empty or already carries a
    ///      scheme. Collections store bare IPFS CIDs; consumers (ENSIP-12
    ///      avatars, ERC721 metadata) need full URIs.
    function prefixUnlessUri(
        string memory prefix,
        string memory value
    ) internal pure returns (string memory) {
        if (bytes(value).length == 0 || hasScheme(value)) return value;
        return string.concat(prefix, value);
    }
}

